import{c as s,Q as t,j as o,m as a}from"./chunks/framework.DjobWxAB.js";const b=JSON.parse('{"title":"RBQ SDK (C++)","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/rbq-sdk.md","filePath":"ko/software/rbq-sdk.md","lastUpdated":1779182288000}'),r={name:"ko/software/rbq-sdk.md"};function d(i,e,l,n,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="rbq-sdk-c" tabindex="-1">RBQ SDK (C++) <a class="header-anchor" href="#rbq-sdk-c" aria-label="Permalink to &quot;RBQ SDK (C++)&quot;">​</a></h1><p><strong>RBQ SDK</strong>는 <strong>Eclipse Cyclone DDS</strong>를 통해 RBQ 소프트웨어 스택과 통신하는 C++ 애플리케이션을 만들기 위한 라이브러리입니다. DDS 참가자·토픽·생성된 메시지 타입을 감싸고, 저수준 제어(관절 레퍼런스, 학습 정책, 타이밍, 필터 등)를 위한 헬퍼를 제공합니다.</p><h2 id="sdk-구성" tabindex="-1">SDK 구성 <a class="header-anchor" href="#sdk-구성" aria-label="Permalink to &quot;SDK 구성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>역할</th></tr></thead><tbody><tr><td><strong>DDS 입출력</strong></td><td><code>Publisher</code> / <code>Subscriber</code> 템플릿 (<code>rbq_sdk/dds/</code>) — 이름이 지정된 토픽에 CycloneDDS-CXX reader/writer.</td></tr><tr><td><strong>메시지</strong></td><td><code>rbq_sdk/idl/</code>의 IDL → C++ 타입 (<code>rbq_msgs</code>, <code>sensor_msgs</code> 등 네임스페이스). <strong>RBQ 전용</strong> 타입, <strong>ROS2와 호환되는</strong> 일부 타입, 빌드에 포함된 <strong>Go2 호환</strong> 타입 등이 있습니다.</td></tr><tr><td><strong>제어 헬퍼</strong></td><td>예: <code>JointControl</code>, <code>Policy</code> / <code>PolicyParams</code> (ONNX + <code>info.json</code>), <code>Filter</code>, <code>Timer</code>, <code>Thread</code>(RT 스레드 옵션).</td></tr></tbody></table><h2 id="요구-사항" tabindex="-1">요구 사항 <a class="header-anchor" href="#요구-사항" aria-label="Permalink to &quot;요구 사항&quot;">​</a></h2><ul><li>개발 PC 기준으로 이 저장소에서는 <strong>Ubuntu 22.04 (x86_64)</strong> 가 일반적입니다.</li><li><strong>CMake</strong> ≥ 3.22, <strong>C++17</strong> 컴파일러.</li><li><strong>Cyclone DDS</strong>: 저장소에 <code>rbq_sdk/3rdparty/</code>로 묶여 있으며, 최초 빌드 시 DDS 부트스트랩 스크립트가 필요합니다(아래 참고).</li></ul><h2 id="빌드-및-설치-rbq-sdk" tabindex="-1">빌드 및 설치 (<code>rbq_sdk/</code>) <a class="header-anchor" href="#빌드-및-설치-rbq-sdk" aria-label="Permalink to &quot;빌드 및 설치 (`rbq_sdk/`)&quot;">​</a></h2><p>RBQ 저장소의 <strong><code>rbq_sdk</code></strong> 디렉터리에서:</p><ol><li><p><strong>최초 1회</strong> — 번들 CycloneDDS 빌드:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build_dds.bash</span></span></code></pre></div></li><li><p><strong>설정·빌드·설치</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div></li></ol><p>설치 레이아웃에는 <code>include/rbq_sdk/</code> 및 생성된 IDL 헤더가 포함됩니다. CMake가 패키지를 찾지 못하면 설치 접두어를 <code>CMAKE_PREFIX_PATH</code>에 넣으세요.</p><h2 id="헤더·네임스페이스" tabindex="-1">헤더·네임스페이스 <a class="header-anchor" href="#헤더·네임스페이스" aria-label="Permalink to &quot;헤더·네임스페이스&quot;">​</a></h2><ul><li><strong>진입점</strong>: 제공되는 경우 <code>rbq_sdk/rbq_sdk.hpp</code>.</li><li><strong>DDS</strong>: <code>rbq_sdk/dds/Publisher.hpp</code>, <code>Subscriber.hpp</code></li><li><strong>생성 IDL</strong>: <code>#include &lt;rbq_sdk/idl/rbq/...&gt;</code></li></ul><p>앱에서 쓰는 토픽 이름은 문자열(예: <code>rt/rbq/...</code>)이며, 정확한 목록은 예제 또는 드라이버 문서를 참고하세요.</p><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><strong>저수준 개발 흐름</strong>: <a href="/RBQ/ko/manual/Guides/developer-level-0.html">Level 0 개발자 가이드</a></li><li><strong>예제 애플리케이션</strong>: <a href="/RBQ/ko/software/examples/rbq_example_Level0.html">rbq_example_level_0</a></li><li><strong>ROS 2 연동</strong>: <a href="/RBQ/ko/software/ROS2.html">ROS2</a></li></ul>',15)])])}const g=s(r,[["render",d]]);export{b as __pageData,g as default};
